use vstd::prelude::*;

verus! {

spec fn le_vec(a: Seq<i8>, b: Seq<i8>) -> Seq<bool>
    recommends a.len() == b.len()
{
    Seq::new(a.len(), |i: int| a[i] <= b[i])
}

fn less_equal(a: Vec<i8>, b: Vec<i8>) -> (out: Vec<bool>)
    requires
        a.len() == b.len(),
    ensures
        out@ == le_vec(a@, b@),
        out@.len() == a@.len(),
{
    assert_eq!(a.len(), b.len());

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x <= y)
        .collect()
}

} // verus!

